    const slot = String(slotValue || '').trim();
    if (!slot) return '';
    const explicitName = String((namesMap && namesMap[slot]) || '').trim();
    if (explicitName) {
      return `${slot}. ${explicitName}`;
    }
    return `${slot}.`;
