    isProcessingQueue = false;
    processingQueueSessionId = null;
    pendingVADChunks = [];
    audioFrames = [];
    chunkProcessingLock = false;
    pendingStop = false;
    clearInterval(completionTimerInterval);
    completionTimerInterval = null;

